// ⚠️ Diferente da migração de Tarefas, esta lógica NUNCA foi validada contra um
// JSON real de tarefa da lista "Planejamentos (Roadmaps)" — só o padrão de
// 'cliente_relacionado' foi confirmado (é o mesmo campo reaproveitado em
// todo o workspace). Rode manualmente e confira o resultado antes de confiar.

function findField(task, pattern, type) {
  return (task.custom_fields || []).find(f => {
    const nameMatch = (f.name || '').toLowerCase().includes(pattern);
    return type ? (nameMatch && f.type === type) : nameMatch;
  });
}

function resolveRelatedId(field) {
  if (!field || !Array.isArray(field.value) || field.value.length === 0) return null;
  return field.value[0].id || null;
}

const allTasks = $input.all().map(item => item.json);

const macroplans = allTasks.map(t => {
  const clienteField = findField(t, 'cliente_relacionado');

  return {
    clickup_task_id: t.id,
    client_clickup_id: resolveRelatedId(clienteField),
    title: t.name,
    clickup_status: (t.status && t.status.status) || 'draft',
    description: t.text_content || t.description || null,
    period_start: null,
    period_end: null,
    creator_email: t.creator ? t.creator.email : null,
    responsible_email: (t.assignees && t.assignees[0]) ? t.assignees[0].email : null,
    attachments: [],
    deleted: false,
  };
});

return [{ json: { macroplans } }];

